19363:         const cost=treasureChestCost(lotId);
19364:         if (!cost || !treasureChestAffordable(cost)) return;
19365:         const unbought=treasureChestUnboughtCount(lotId);
19366:         if (unbought===0) return;
19367:         const digging=/^mf_treasurelot_chest_digging_spot_sl\d+$/.test(lotId);
19368:         const chest=/^mf_treasurelot_chest_type_(?:01|015|02|03)$/.test(lotId);
19369:         if (!digging && !chest) return;
19370:         // Canon: completely excavate every currently affordable digging spot
19371:         // before spending time/resources on already uncovered chests.
19372:         // Key chests remain available as a recovery path when energy is below 5;
19373:         // if they return energy, digging immediately becomes the top priority again.
19374:         let priority=digging ? 1000 : 300;
19375:         if (lotId==='mf_treasurelot_chest_type_03') priority+=40;
19376:         else if (lotId==='mf_treasurelot_chest_type_02') priority+=30;
19377:         else if (lotId==='mf_treasurelot_chest_type_015') priority+=20;
19378:         else if (lotId==='mf_treasurelot_chest_type_01') priority=180;
19379:         candidates.push({...row,cost,digging,chest,priority,index});
19380:       });
19381:       candidates.sort((a,b)=>b.priority-a.priority || a.index-b.index);
19382:       return candidates[0] || null;
19383:     }
